<?php
if (PHP_SAPI !== 'cli' && (get_included_files()[0] ?? null) === __FILE__) { http_response_code(404); exit; }
require_once __DIR__ . '/../core/UserAdministration.php';
require_once __DIR__ . '/../core/ProviderUserActions.php';
Identity::requireIdentity('backend', true);
$usersDb = HttpSecurity::connection(); $usersService = new UserAdministration($usersDb, new ServiceManager());
$realm = ($_POST['realm'] ?? $_GET['realm'] ?? '') === 'customer' ? 'customer' : 'backend'; $notice = ''; $failure = '';
if (($_SERVER['REQUEST_METHOD'] ?? 'GET') === 'POST' && isset($_POST['user_operation'])) {
    try {
        switch ($_POST['user_operation']) {
            case 'save': $result = $usersService->save($realm, $_POST); break;
            case 'delete': $result = $usersService->delete($realm, (int) ($_POST['id'] ?? 0), (array) ($_POST['delete_from_systems'] ?? [])); break;
            case 'reset': $result = $usersService->requestReset($realm, (int) ($_POST['id'] ?? 0)); break;
            case 'provider': $result = (new ProviderUserActions(new ServiceManager()))->execute((string) ($_POST['provider'] ?? ''), (string) ($_POST['provider_action'] ?? ''), $_POST); break;
            default: throw new InvalidArgumentException('Unbekannte Benutzeraktion');
        }
        if (!empty($result['success'])) $notice = $result['message'] ?? 'Aktion abgeschlossen.';
        else $failure = $result['message'] ?? 'Aktion nicht bestätigt.';
    } catch (InvalidArgumentException $e) { $failure = $e->getMessage(); }
    catch (Throwable $e) { error_log('User administration failed: ' . get_class($e)); $failure = 'Die Aktion kann gerade nicht verarbeitet werden. Eingaben und vorhandene Verknüpfungen prüfen.'; }
}
$accounts = $usersService->listing($realm); $editing = null;
foreach ($accounts as $account) if ((int) $account['id'] === (int) ($_GET['edit'] ?? 0)) $editing = $account;
$escapeUser = fn($value) => htmlspecialchars((string) $value, ENT_QUOTES | ENT_SUBSTITUTE, 'UTF-8');
?>
<section class="container-fluid" aria-labelledby="users-title"><h1 id="users-title">Benutzerverwaltung</h1><p><a href="?option=users&amp;realm=backend">Verwaltung</a> · <a href="?option=users&amp;realm=customer">Kunden</a></p>
<?php if ($notice): ?><p class="alert alert-success" role="status"><?= $escapeUser($notice) ?></p><?php endif; ?><?php if ($failure): ?><p class="alert alert-danger" role="alert"><?= $escapeUser($failure) ?></p><?php endif; ?>
<div class="table-responsive"><table class="table"><caption><?= $realm === 'backend' ? 'Verwaltungsbenutzer' : 'Kundenkonten' ?></caption><thead><tr><th scope="col">ID</th><th scope="col">Name</th><th scope="col">E-Mail</th><th scope="col">Status/Rolle</th><th scope="col">Aktionen</th></tr></thead><tbody>
<?php foreach ($accounts as $account): ?><tr><td><?= (int) $account['id'] ?></td><td><?= $escapeUser($account['username'] ?? trim(($account['first_name'] ?? '') . ' ' . ($account['last_name'] ?? ''))) ?></td><td><?= $escapeUser($account['email']) ?></td><td><?= $escapeUser($account['status'] ?? ($account['role'] . '/' . $account['active'])) ?></td><td><a href="?option=users&amp;realm=<?= $realm ?>&amp;edit=<?= (int) $account['id'] ?>">Bearbeiten</a><form method="post" class="d-inline"><?= HttpSecurity::csrfField() ?><input type="hidden" name="realm" value="<?= $realm ?>"><input type="hidden" name="id" value="<?= (int) $account['id'] ?>"><button class="btn btn-sm btn-outline-primary" name="user_operation" value="reset" type="submit">Rücksetzlink senden</button></form></td></tr><?php endforeach; ?></tbody></table></div>
<h2><?= $editing ? 'Konto bearbeiten' : 'Konto anlegen' ?></h2><form method="post" class="row g-3"><?= HttpSecurity::csrfField() ?><input type="hidden" name="realm" value="<?= $realm ?>"><input type="hidden" name="id" value="<?= (int) ($editing['id'] ?? 0) ?>">
<?php foreach (($realm === 'backend' ? ['username'=>'Benutzername','full_name'=>'Vollständiger Name'] : ['first_name'=>'Vorname','last_name'=>'Nachname','company'=>'Firma','phone'=>'Telefon']) + ['email'=>'E-Mail-Adresse'] as $field=>$label): ?><div class="col-md-6"><label class="form-label" for="user-<?= $field ?>"><?= $label ?></label><input class="form-control" id="user-<?= $field ?>" name="<?= $field ?>" type="<?= $field === 'email' ? 'email' : 'text' ?>" maxlength="<?= in_array($field,['username','first_name','last_name'],true) ? 100 : ($field === 'phone' ? 50 : 254) ?>" value="<?= $escapeUser($editing[$field] ?? '') ?>" <?= in_array($field,['username','first_name','last_name','email'],true) ? 'required' : '' ?>></div><?php endforeach; ?>
<?php $choices = $realm === 'backend' ? ['role'=>['admin','user','moderator','readonly'],'active'=>['y','n']] : ['status'=>['pending','active','suspended','deleted']]; foreach ($choices as $field=>$values): ?><div class="col-md-6"><label class="form-label" for="user-<?= $field ?>"><?= $field ?></label><select class="form-select" id="user-<?= $field ?>" name="<?= $field ?>"><?php foreach ($values as $value): ?><option value="<?= $value ?>" <?= ($editing[$field] ?? ($field === 'role' ? 'user' : $values[0])) === $value ? 'selected' : '' ?>><?= $value ?></option><?php endforeach; ?></select></div><?php endforeach; ?>
<div class="col-12"><label class="form-label" for="user-password"><?= $editing ? 'Neues Passwort (optional; alternativ Rücksetzlink)' : 'Anfangspasswort' ?></label><input class="form-control" id="user-password" name="password" type="password" minlength="12" maxlength="4096" autocomplete="new-password" <?= $editing ? '' : 'required' ?>><p>Passwörter werden nicht per E-Mail versendet. Providerkonten werden separat und ausdrücklich verwaltet.</p></div><div class="col-12"><button class="btn btn-primary" type="submit" name="user_operation" value="save">Speichern</button><?php if ($editing): ?> <button class="btn btn-outline-danger" type="submit" name="user_operation" value="delete" formnovalidate>Lokales Konto löschen</button><?php endif; ?></div></form>
<details class="mt-4"><summary>Providerbenutzer ausdrücklich verwalten</summary><p>Dies ändert das ausgewählte externe Konto. OGP erlaubt hier nur Auflisten, Anlegen und Löschen; andere Änderungen erfolgen im OGP-Portal.</p><form method="post" class="row g-3"><?= HttpSecurity::csrfField() ?><input type="hidden" name="realm" value="<?= $realm ?>"><div class="col-md-6"><label for="provider">Anbieter</label><select class="form-select" id="provider" name="provider"><option value="proxmox">Proxmox (pve)</option><option value="ispconfig">ISPConfig</option><option value="ogp">OGP</option></select></div><div class="col-md-6"><label for="provider-action">Aktion</label><select class="form-select" id="provider-action" name="provider_action"><option value="list">Auflisten</option><option value="create">Anlegen</option><option value="edit">Name/E-Mail ändern (Proxmox/ISPConfig)</option><option value="password">Passwort ändern (Proxmox/ISPConfig)</option><option value="delete">Löschen</option></select></div><?php foreach (['external_id'=>'Vorhandene Provider-ID','username'=>'Neuer Benutzername','name'=>'Name','email'=>'E-Mail-Adresse','password'=>'Neues Passwort'] as $field=>$label): ?><div class="col-md-6"><label for="provider-<?= $field ?>"><?= $label ?></label><input class="form-control" id="provider-<?= $field ?>" name="<?= $field ?>" type="<?= $field === 'password' ? 'password' : ($field === 'email' ? 'email' : 'text') ?>" maxlength="<?= $field === 'password' ? 4096 : 254 ?>" autocomplete="<?= $field === 'password' ? 'new-password' : 'off' ?>"></div><?php endforeach; ?><div class="col-12"><button class="btn btn-outline-primary" type="submit" name="user_operation" value="provider">Provideraktion ausführen</button></div></form><?php if (isset($result['provider'], $result['data']) && is_array($result['data'])): ?><pre><?= $escapeUser(json_encode($result['data'], JSON_PRETTY_PRINT | JSON_UNESCAPED_UNICODE)) ?></pre><?php endif; ?></details></section>
